function Feature({ icon, title, copy }: { icon: string; title: string; copy: string }) { return <article className="feature"><span className="feature-icon">{icon}</span><h3>{title}</h3><p>{copy}</p><span className="feature-arrow">↗</span></article> }
function PriceCard({ name, price, detail, features, featured, onStart }: { name: string; price: string; detail: string; features: string[]; featured?: boolean; onStart: () => void }) { return <article className={featured ? 'price-card featured' : 'price-card'}>{featured && <span className="popular">Most popular</span>}<h3>{name}</h3><p>{detail}</p><div className="price"><strong>KSh {price}</strong><span>/ month</span></div><button className={featured ? 'btn primary' : 'btn secondary'} onClick={onStart}>Get started ↗</button><ul>{features.map((feature) => <li key={feature}>✓ {feature}</li>)}</ul></article> }
function FlowStep({ number, title, detail, icon }: { number: string; title: string; detail: string; icon: string }) { return <div className="flow-step"><span className="flow-number">{number}</span><span className="flow-icon">{icon}</span><div><strong>{title}</strong><small>{detail}</small></div></div> }

